import { test, expect } from '@playwright/test';

test.describe('Drawer/Slide-in Panel from Right', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should open drawer panel from right with correct animation and visibility', async ({ page }) => {
    // Verify initial state: drawer should be closed
    const drawer = page.getByRole('button', { name: /open drawer/i });
    await expect(drawer).not.toBeVisible();

    // Verify main content is visible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Click drawer button to open drawer
    await drawer.click();

    // Verify drawer is now visible and has correct position
    await expect(drawer).toBeVisible();
    const drawerPosition = page.getByRole('region', { name: /drawer/i }).boundingBox();
    expect(drawerPosition.x).toBeGreaterThan(0);
    expect(drawerPosition.y).toBeLessThan(0);

    // Verify drawer has correct animation
    const drawerAnimation = page.getByRole('region', { name: /drawer/i }).shadowRoot().shadowBoundingBox();
    expect(drawerAnimation).toHaveProperty('transform', /translate(-100%, 0)/);

    // Verify drawer content is visible
    const drawerContent = page.getByRole('region', { name: /drawer content/i });
    await expect(drawerContent).toBeVisible();

    // Verify main content is still visible
    await expect(mainContent).toBeVisible();

    // Verify drawer is closed when clicking outside
    const closeButton = page.getByRole('button', { name: /close drawer/i });
    await expect(closeButton).toBeVisible();
    await closeButton.click();

    // Verify drawer is closed
    await expect(drawer).not.toBeVisible();
    await expect(drawerContent).not.toBeVisible();
  });

  test('should handle drawer panel closing with animation and visibility', async ({ page }) => {
    // Open drawer
    const drawer = page.getByRole('button', { name: /open drawer/i });
    await drawer.click();

    // Verify drawer is open
    const drawerPosition = page.getByRole('region', { name: /drawer/i }).boundingBox();
    expect(drawerPosition.x).toBeGreaterThan(0);
    expect(drawerPosition.y).toBeLessThan(0);

    // Verify drawer content is visible
    const drawerContent = page.getByRole('region', { name: /drawer content/i });
    await expect(drawerContent).toBeVisible();

    // Verify main content is still visible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify drawer has correct animation
    const drawerAnimation = page.getByRole('region', { name: /drawer/i }).shadowRoot().shadowBoundingBox();
    expect(drawerAnimation).toHaveProperty('transform', /translate(-100%, 0)/);

    // Close drawer by clicking close button
    const closeButton = page.getByRole('button', { name: /close drawer/i });
    await closeButton.click();

    // Verify drawer is closed
    await expect(drawer).not.toBeVisible();
    await expect(drawerContent).not.toBeVisible();

    // Verify main content is visible again
    await expect(mainContent).toBeVisible();

    // Verify drawer has correct position when closed
    const closedDrawerPosition = page.getByRole('region', { name: /drawer/i }).boundingBox();
    expect(closedDrawerPosition.x).toBeLessThan(0);
    expect(closedDrawerPosition.y).toBeLessThan(0);
  });
});
